/* Isolated UX Lab concept styling. These classes are not used by operational pages. */
.tpz-lab-shell { --tpz-ink: #12212b; --tpz-muted: #6f7e86; --tpz-accent: #d9754d; --tpz-accent-strong: #b95d3a; color: var(--tpz-ink); font-family: 'Instrument Sans', ui-sans-serif, system-ui, sans-serif; }
.dark .tpz-lab-shell { --tpz-ink: #e9f0ef; --tpz-muted: #9aabaa; }
.tpz-lab-aurora { --tpz-wash: #edf3f0; --tpz-panel: rgba(255,255,255,.88); --tpz-line: #dbe6e1; --tpz-glow: #cfe4dc; }
.tpz-lab-executive { --tpz-wash: #f1eee8; --tpz-panel: rgba(255,255,255,.94); --tpz-line: #e3ded4; --tpz-glow: #e7dcc8; --tpz-accent: #9b6b38; --tpz-accent-strong: #765029; }
.tpz-lab-shell { background: var(--tpz-wash); border: 1px solid var(--tpz-line); border-radius: 24px; overflow: hidden; min-height: 720px; }
.tpz-lab-header { display:flex; justify-content:space-between; gap:24px; align-items:flex-end; padding:28px 32px; background:linear-gradient(120deg,var(--tpz-panel),transparent); border-bottom:1px solid var(--tpz-line); }
.tpz-eyebrow { color:var(--tpz-accent-strong); font-size:10px; letter-spacing:.16em; font-weight:800; }
.tpz-title { margin-top:5px; font-size:clamp(24px,3vw,38px); letter-spacing:-.04em; font-weight:750; }
.tpz-muted, .tpz-section-heading p { color:var(--tpz-muted); font-size:13px; }
.tpz-lab-layout { display:flex; min-height:650px; }
.tpz-lab-sidebar { width:238px; padding:22px 14px; border-right:1px solid var(--tpz-line); background:rgba(255,255,255,.38); position:relative; transition:width .2s ease; }
.tpz-lab-sidebar.is-collapsed { width:72px; }
.tpz-brand { display:flex; align-items:center; gap:10px; padding:0 10px 18px; font-weight:800; font-size:13px; }
.tpz-brand-mark { display:grid; place-items:center; width:31px; height:31px; background:var(--tpz-ink); color:var(--tpz-wash); border-radius:10px; font-size:10px; letter-spacing:-.08em; }
.tpz-collapse { position:absolute; top:24px; right:-12px; width:24px; height:24px; border:1px solid var(--tpz-line); background:var(--tpz-panel); border-radius:50%; font-size:12px; z-index:2; }
.tpz-nav-item { display:flex; width:100%; align-items:center; gap:11px; padding:10px 11px; border-radius:10px; color:var(--tpz-muted); font-size:12px; text-align:left; transition:all .15s ease; }
.tpz-nav-item:hover, .tpz-nav-item.is-active { background:var(--tpz-panel); color:var(--tpz-ink); box-shadow:0 3px 16px rgba(25,47,43,.05); }
.tpz-nav-item.is-active { border-left:3px solid var(--tpz-accent); padding-left:8px; font-weight:700; }
.tpz-nav-icon { width:20px; text-align:center; font-size:17px; }
.tpz-sidebar-foot { position:absolute; bottom:22px; left:24px; right:20px; color:var(--tpz-muted); font-size:11px; line-height:1.5; }
.tpz-lab-main { min-width:0; flex:1; padding:0 30px 32px; }
.tpz-topbar { height:68px; display:flex; align-items:center; justify-content:space-between; gap:18px; border-bottom:1px solid var(--tpz-line); }
.tpz-search { display:flex; align-items:center; gap:8px; width:min(420px,100%); padding:9px 12px; background:var(--tpz-panel); border:1px solid var(--tpz-line); border-radius:10px; color:var(--tpz-muted); }
.tpz-search input { width:100%; outline:0; background:transparent; border:0; font-size:12px; color:var(--tpz-ink); }
.tpz-icon-button { position:relative; color:var(--tpz-muted); font-size:19px; }.tpz-notification-dot { position:absolute; top:1px; right:0; width:5px; height:5px; border-radius:50%; background:var(--tpz-accent); }
.tpz-avatar { display:grid; place-items:center; width:31px; height:31px; background:var(--tpz-ink); color:white; border-radius:50%; font-size:10px; font-weight:700; }
.tpz-breadcrumb { display:flex; gap:9px; align-items:center; padding:18px 0 12px; color:var(--tpz-muted); font-size:11px; }.tpz-breadcrumb strong { color:var(--tpz-ink); }
.tpz-hero { display:flex; align-items:flex-end; justify-content:space-between; gap:18px; padding:16px 0 22px; }.tpz-hero h2 { margin-top:4px; font-size:28px; font-weight:750; letter-spacing:-.04em; }.tpz-hero p { color:var(--tpz-muted); font-size:13px; margin-top:5px; }
.tpz-section-heading { display:flex; justify-content:space-between; align-items:flex-end; gap:16px; margin:22px 0 12px; }.tpz-section-heading h3 { font-size:17px; font-weight:750; letter-spacing:-.02em; }.tpz-section-heading p { margin-top:3px; }
.tpz-live-pill { display:flex; gap:7px; align-items:center; color:var(--tpz-muted); font-size:11px; }.tpz-live-pill i { width:7px; height:7px; background:#6fae83; border-radius:50%; }
.tpz-action-grid, .tpz-order-table { border:1px solid var(--tpz-line); border-radius:14px; overflow:hidden; background:var(--tpz-panel); }.tpz-action-row { display:flex; gap:12px; align-items:center; width:100%; padding:14px 16px; border-bottom:1px solid var(--tpz-line); transition:background .15s ease; }.tpz-action-row:last-child { border-bottom:0; }.tpz-action-row:hover, .tpz-table-row:hover { background:rgba(217,117,77,.06); }.tpz-row-icon { display:grid; place-items:center; width:28px; height:28px; background:var(--tpz-glow); border-radius:9px; color:var(--tpz-accent-strong); }.tpz-action-row strong, .tpz-table-row strong { display:block; font-size:12px; }.tpz-action-row small, .tpz-table-row small { display:block; margin-top:3px; color:var(--tpz-muted); font-size:11px; }.tpz-status { color:var(--tpz-accent-strong); font-size:11px; white-space:nowrap; }
.tpz-signal-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:10px; }.tpz-signal { padding:15px; background:var(--tpz-panel); border:1px solid var(--tpz-line); border-radius:14px; }.tpz-signal span, .tpz-signal small { display:block; color:var(--tpz-muted); font-size:11px; }.tpz-signal strong { display:block; margin:8px 0 4px; font-size:24px; letter-spacing:-.04em; }
.tpz-work-tabs { display:flex; gap:18px; margin-bottom:12px; border-bottom:1px solid var(--tpz-line); }.tpz-work-tabs button { padding:9px 0; color:var(--tpz-muted); font-size:12px; border-bottom:2px solid transparent; }.tpz-work-tabs button.is-active { color:var(--tpz-accent-strong); border-color:var(--tpz-accent); font-weight:700; }
.tpz-table-head, .tpz-table-row { display:grid; grid-template-columns:2fr 1fr 1fr 1fr; gap:12px; align-items:center; padding:12px 15px; text-align:left; font-size:11px; }.tpz-table-head { color:var(--tpz-muted); text-transform:uppercase; letter-spacing:.1em; font-size:9px; border-bottom:1px solid var(--tpz-line); }.tpz-table-row { width:100%; border-bottom:1px solid var(--tpz-line); }.tpz-table-row:last-child { border-bottom:0; }
.tpz-inventory-layout { display:grid; grid-template-columns:minmax(0,1.5fr) minmax(220px,1fr); gap:14px; }.tpz-inventory-note { padding:22px; background:var(--tpz-ink); color:#eef4f1; border-radius:14px; }.tpz-inventory-note p { color:#afc1bc; font-size:12px; line-height:1.6; margin-top:8px; }.tpz-mini-chart { display:flex; align-items:flex-end; gap:5px; height:70px; margin-top:22px; }.tpz-mini-chart i { width:13%; background:var(--tpz-accent); border-radius:4px 4px 1px 1px; }
.tpz-empty-concept { display:grid; place-items:center; min-height:280px; padding:36px; text-align:center; background:var(--tpz-panel); border:1px dashed var(--tpz-line); border-radius:16px; }.tpz-empty-orbit { display:grid; place-items:center; width:58px; height:58px; border:1px solid var(--tpz-accent); border-radius:50%; color:var(--tpz-accent); font-size:24px; }.tpz-empty-concept h3 { margin-top:14px; font-size:18px; }.tpz-empty-concept p { max-width:420px; margin:6px 0 16px; color:var(--tpz-muted); font-size:13px; }
.tpz-feedback-panel { display:flex; align-items:center; gap:20px; padding:16px; background:var(--tpz-panel); border:1px solid var(--tpz-line); border-radius:14px; }.tpz-feedback-panel h3 { margin-top:4px; font-size:14px; font-weight:750; }.tpz-feedback-panel p { color:var(--tpz-muted); font-size:11px; }.tpz-feedback-input { flex:1; min-width:180px; border:1px solid var(--tpz-line); border-radius:9px; padding:9px; background:transparent; font-size:12px; outline:0; }
.tpz-overlay { position:fixed; inset:0; z-index:40; background:rgba(8,20,24,.38); backdrop-filter:blur(3px); }.tpz-drawer, .tpz-modal { position:fixed; z-index:50; background:var(--tpz-panel); box-shadow:0 20px 70px rgba(8,20,24,.18); }.tpz-drawer { top:0; right:0; bottom:0; width:min(420px,100%); padding:30px; }.tpz-modal { top:8%; left:50%; width:min(620px,calc(100% - 30px)); transform:translateX(-50%); padding:28px; border-radius:18px; }.tpz-drawer-close { float:right; font-size:22px; color:var(--tpz-muted); }.tpz-drawer h2, .tpz-modal h2 { margin-top:16px; font-size:24px; font-weight:750; }.tpz-drawer-block { margin:22px 0; padding:14px; background:var(--tpz-wash); border-radius:10px; font-size:12px; }.tpz-drawer-block p { margin-top:5px; color:var(--tpz-muted); }.tpz-stepper { display:flex; gap:7px; margin:24px 0; }.tpz-stepper span { flex:1; border-bottom:2px solid var(--tpz-line); padding-bottom:8px; color:var(--tpz-muted); font-size:10px; }.tpz-stepper span.is-active { color:var(--tpz-accent-strong); border-color:var(--tpz-accent); font-weight:700; }.tpz-product-row { display:flex; align-items:center; gap:12px; width:100%; padding:12px; border:1px solid var(--tpz-line); border-radius:10px; text-align:left; font-size:11px; }.tpz-product-row:hover { border-color:var(--tpz-accent); background:var(--tpz-wash); }.tpz-product-row span:first-child { flex:1; }.tpz-product-row strong, .tpz-product-row small { display:block; }.tpz-product-row small { margin-top:3px; color:var(--tpz-muted); }.tpz-success-state { padding:22px; border-radius:10px; background:#e7f3ea; color:#39724d; font-size:13px; }
@media (max-width: 800px) { .tpz-lab-header, .tpz-feedback-panel, .tpz-hero { align-items:flex-start; flex-direction:column; }.tpz-lab-sidebar { width:72px; }.tpz-lab-sidebar .tpz-sidebar-foot { display:none; }.tpz-lab-main { padding:0 16px 24px; }.tpz-signal-grid, .tpz-inventory-layout { grid-template-columns:1fr; }.tpz-table-head, .tpz-table-row { grid-template-columns:2fr 1fr 1fr; }.tpz-table-head span:nth-child(3), .tpz-table-row > span:nth-child(3) { display:none; }.tpz-action-row { padding:12px; }.tpz-title { font-size:25px; } }

