    .tpz-modal, .tpz-drawer { --tpz-panel:#fff; --tpz-ink:#12212b; --tpz-wash:#edf3f0; --tpz-line:#dbe6e1; --tpz-muted:#627780; --tpz-accent:#d9754d; --tpz-accent-strong:#b95d3a; color:var(--tpz-ink); }
